import { useEffect } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  ArrowLeft, ArrowRight, LayoutGrid, Users, Shield,
  CheckCircle2, Circle, Wrench, Loader2, Activity,
} from "lucide-react";
import {
  getDivision,
  DIVISION_CATEGORY_LABELS,
  type CompanyDivision,
} from "@/config/company-divisions";
import { MODULE_ICONS } from "@/config/platform-modules";
import { FeatureAccessDenied } from "@/components/FeatureAccessDenied";
import { useRole } from "@/contexts/RoleContext";
import { useDivisionMetrics, usePlatformHealth } from "@/hooks/useCompanyLiveData";

function LiveStatusStrip({ divisionId, division }: { divisionId: string; division: CompanyDivision }) {
  const { data: health, isLoading: healthLoading } = usePlatformHealth();
  const { data: metrics, isLoading: metricsLoading } = useDivisionMetrics(divisionId);
  const liveToolCount = division.tools.filter((t) => t.live).length;
  const buildingCount = division.tools.filter((t) => !t.live).length;

  const healthLabel =
    healthLoading ? "Checking…"
    : health === "operational" ? "Operational"
    : health === "degraded" ? "Degraded"
    : "Status unknown";

  const healthClass =
    health === "operational" ? "text-emerald-400"
    : health === "degraded" ? "text-amber-400"
    : "text-slate-400";

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-4 rounded-xl border border-white/10 bg-white/[0.03] px-4 py-3 text-xs">
        <span className="flex items-center gap-2 text-slate-400">
          {healthLoading ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin text-slate-500" />
          ) : health === "operational" ? (
            <>
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-50" />
                <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500" />
              </span>
              <span className={`font-semibold ${healthClass}`}>{healthLabel}</span>
            </>
          ) : (
            <>
              <Wrench className="h-3.5 w-3.5 text-amber-400" />
              <span className={`font-semibold ${healthClass}`}>{healthLabel}</span>
            </>
          )}
          <span className="text-slate-600">· live DB health</span>
        </span>
        <span className="flex items-center gap-1.5 text-slate-500">
          <CheckCircle2 className="h-3.5 w-3.5 text-emerald-400/70" />
          {liveToolCount} live tool{liveToolCount !== 1 ? "s" : ""}
        </span>
        {buildingCount > 0 && (
          <span className="flex items-center gap-1.5 text-slate-500">
            <Circle className="h-3.5 w-3.5 text-amber-400/70" />
            {buildingCount} in roadmap
          </span>
        )}
        <span className="flex items-center gap-1.5 text-slate-500">
          <Users className="h-3.5 w-3.5" />
          {division.roles.length} roles
        </span>
      </div>

      {metricsLoading ? (
        <div className="text-xs text-muted-foreground animate-pulse flex items-center gap-2">
          <Activity className="h-3.5 w-3.5" /> Loading division KPIs…
        </div>
      ) : metrics && metrics.length > 0 ? (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {metrics.map((m) => (
            <Card key={m.label} className="border-border/50 bg-card/40 h-full">
              <CardContent className="pt-4 pb-3">
                <p className="text-2xl font-bold tabular-nums">{m.value}</p>
                <p className="text-[10px] uppercase tracking-wider text-muted-foreground mt-1">{m.label}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export default function DepartmentPortal() {
  const { divisionId } = useParams<{ divisionId: string }>();
  const navigate = useNavigate();
  const { isAdmin } = useRole();
  const division = divisionId ? getDivision(divisionId) : undefined;

  useEffect(() => {
    if (division?.workspaceRoute) {
      navigate(division.workspaceRoute, { replace: true });
    }
  }, [division, navigate]);

  if (!division) {
    return (
      <div className="container mx-auto px-4 py-16 text-center">
        <p className="text-muted-foreground">Division not found.</p>
        <Button asChild variant="outline" className="mt-4">
          <Link to="/hub">Back to Platform Hub</Link>
        </Button>
      </div>
    );
  }

  if (division.adminOnly && !isAdmin) {
    return <FeatureAccessDenied />;
  }

  const Icon = MODULE_ICONS[division.icon] ?? Shield;
  const liveTools = division.tools.filter((t) => t.live);
  const buildingTools = division.tools.filter((t) => !t.live);

  return (
    <div className="min-h-screen bg-background">
      <div
        className="pointer-events-none fixed inset-0 opacity-30"
        style={{
          background: `radial-gradient(ellipse 70% 50% at 50% -10%, rgba(6,182,212,0.12), transparent)`,
        }}
      />

      <header className="sticky top-0 z-40 border-b border-border/40 header-glass">
        <div className="container mx-auto flex h-14 items-center gap-3 px-4">
          <Button variant="ghost" size="sm" asChild className="text-muted-foreground">
            <Link to="/hub">
              <ArrowLeft className="h-4 w-4 mr-1.5" />
              Platform Hub
            </Link>
          </Button>
          <span className="text-slate-600">/</span>
          <span className="text-sm font-medium text-foreground truncate">{division.title}</span>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 max-w-6xl relative">
        {/* Hero */}
        <div className="mb-8 flex flex-col gap-6 lg:flex-row lg:items-start">
          <div
            className={`flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl bg-gradient-to-br ${division.gradient} shadow-lg`}
          >
            <Icon className="h-8 w-8 text-white" />
          </div>
          <div className="flex-1">
            <Badge variant="outline" className="mb-2 text-[10px] uppercase tracking-widest">
              {DIVISION_CATEGORY_LABELS[division.category]}
            </Badge>
            <h1 className="text-2xl md:text-3xl font-bold tracking-tight">{division.title}</h1>
            <p className="text-cyan-400/90 text-sm font-medium mt-1">{division.tagline}</p>
            <p className="text-muted-foreground mt-3 max-w-2xl leading-relaxed">{division.description}</p>
          </div>
        </div>

        <LiveStatusStrip divisionId={division.id} division={division} />

        {/* Roles */}
        <Card className="mt-8 border-border/60">
          <CardHeader className="pb-2">
            <CardTitle className="text-base flex items-center gap-2">
              <Users className="h-4 w-4 text-cyan-400" />
              Team roles
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex flex-wrap gap-2">
              {division.roles.map((role) => (
                <Badge key={role} variant="secondary" className="font-normal">
                  {role}
                </Badge>
              ))}
            </div>
            {division.frameworks && (
              <div className="mt-4 pt-4 border-t border-border/40">
                <p className="text-xs text-muted-foreground uppercase tracking-wider mb-2">Frameworks</p>
                <div className="flex flex-wrap gap-2">
                  {division.frameworks.map((fw) => (
                    <Badge key={fw} variant="outline" className="border-violet-500/30 text-violet-400">
                      {fw}
                    </Badge>
                  ))}
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Live tools */}
        <div className="mt-8">
          <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
            <CheckCircle2 className="h-5 w-5 text-emerald-400" />
            Live tools
          </h2>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 auto-rows-fr">
            {liveTools.map((tool) => (
              <Card
                key={tool.label}
                className="border-cyan-500/15 hover:border-cyan-400/35 transition-all cursor-pointer group h-full"
                onClick={() => navigate(tool.route)}
                onKeyDown={(e) => e.key === "Enter" && navigate(tool.route)}
                role="button"
                tabIndex={0}
              >
                <CardContent className="pt-5 pb-4">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <p className="font-medium text-foreground group-hover:text-cyan-300 transition-colors">
                        {tool.label}
                      </p>
                      {tool.description && (
                        <p className="text-xs text-muted-foreground mt-1">{tool.description}</p>
                      )}
                    </div>
                    <ArrowRight className="h-4 w-4 text-slate-600 group-hover:text-cyan-400 shrink-0 mt-0.5 transition-all group-hover:translate-x-0.5" />
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>

        {/* Building */}
        {buildingTools.length > 0 && (
          <div className="mt-8">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Circle className="h-5 w-5 text-amber-400" />
              Roadmap
            </h2>
            <div className="grid gap-3 sm:grid-cols-2">
              {buildingTools.map((tool) => (
                <div
                  key={tool.label}
                  className="rounded-xl border border-dashed border-amber-500/20 bg-amber-500/5 px-4 py-3"
                >
                  <p className="text-sm font-medium text-amber-200/90">{tool.label}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">{tool.description}</p>
                  <Badge variant="outline" className="mt-2 text-[10px] border-amber-500/30 text-amber-400">
                    Planned
                  </Badge>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="mt-12 flex flex-wrap gap-3">
          <Button asChild variant="outline" size="sm">
            <Link to="/hub">
              <LayoutGrid className="h-4 w-4 mr-1.5" />
              All divisions
            </Link>
          </Button>
          {liveTools[0] && (
            <Button size="sm" onClick={() => navigate(liveTools[0].route)}>
              Open primary workspace
              <ArrowRight className="h-4 w-4 ml-1.5" />
            </Button>
          )}
        </div>
      </main>
    </div>
  );
}
